  1	/**
  2	 * GUI API Route Handlers — Model Registry Domain
  3	 *
  4	 * All REST handlers for the /api/models, /api/model-assignments, and
  5	 * /api/personas endpoints. Follows the domain-split pattern established by
  6	 * `api-repos.ts` — each API domain gets its own handler file imported from
  7	 * `server.ts`.
  8	 *
  9	 * Routes provided:
 10	 *   GET    /api/models                       — list models (auto-init local.json from defaults)
 11	 *   PUT    /api/models                       — bulk-save model list (auto-assign UUIDs)
 12	 *   POST   /api/models/load-defaults         — merge default.json into local.json
 13	 *   GET    /api/model-assignments            — get assignments enriched with stale flag
 14	 *   PUT    /api/model-assignments            — validate + persist assignment data
 15	 *   POST   /api/model-assignments/replace    — swap all occurrences of one model UUID
 16	 *   GET    /api/personas                     — list personas from name-mapping.json
 17	 *   POST   /api/personas/rebuild             — spawn node scripts/build-personas.js
 18	 *
 19	 * Validation rules:
 20	 *   - `PUT /api/models`: auto-assigns UUIDv4 to entries missing `id`; rejects
 21	 *     duplicate slugs and the reserved slug `"inherit"` on non-sentinel entries.
 22	 *   - `PUT /api/models`: returns 409 Conflict when a deletion would leave a
 23	 *     referenced model with no replacement (user must use Replace Model first).
 24	 *   - `PUT /api/model-assignments`: validates all model UUIDs exist in registry
 25	 *     and all persona keys exist in name-mapping.json.
 26	 *   - `POST /api/model-assignments/replace`: rejects same-model swap and
 27	 *     rejects when old_model_id is not currently referenced.
 28	 *
 29	 * Error shape: { error: { code: string, message: string } }
 30	 *   NOT_FOUND        → 404
 31	 *   VALIDATION_ERROR → 400
 32	 *   CONFLICT         → 409
 33	 *   (unhandled)      → 500
 34	 *
 35	 * STDIO discipline: this file never writes to process.stdout.
 36	 */
 37	
 38	import { readFile, stat } from 'fs/promises';
 39	import { join } from 'path';
 40	import { spawn } from 'child_process';
 41	import { randomUUID } from 'crypto';
 42	import { z } from 'zod';
 43	import { ApiError } from '../src/gui/errors.js';
 44	import { WORKSPACE_ROOT } from '../src/utils/ledger-root.js';
 45	import {
 46	  readModels,
 47	  writeModels,
 48	  readAssignments,
 49	  writeAssignments,
 50	  loadDefaults,
 51	  ModelRegistrySchema,
 52	  ModelAssignmentsSchema,
 53	  type ModelEntry,
 54	  type ModelAssignments,
 55	} from '../src/gui/model-registry.js';
 56	
 57	// Re-export ApiError so consumers can catch typed errors without importing
 58	// from a separate path.
 59	export { ApiError };
 60	
 61	// ---------------------------------------------------------------------------
 62	// Private helpers
 63	// ---------------------------------------------------------------------------
 64	
 65	function validationError(message: string, details?: unknown): never {
 66	  throw new ApiError('VALIDATION_ERROR', message, details);
 67	}
 68	
 69	function conflictError(message: string, details?: unknown): never {
 70	  throw new ApiError('CONFLICT', message, details);
 71	}
 72	
 73	/**
 74	 * Returns the absolute path to the model registry directory.
 75	 * `{WORKSPACE_ROOT}/personas/model-registry`
 76	 */
 77	function modelRegistryDir(): string {
 78	  return join(WORKSPACE_ROOT, 'personas', 'model-registry');
 79	}
 80	
 81	/**
 82	 * Returns the absolute path to name-mapping.json.
 83	 * `{WORKSPACE_ROOT}/personas/name-mapping.json`
 84	 */
 85	function nameMappingPath(): string {
 86	  return join(WORKSPACE_ROOT, 'personas', 'name-mapping.json');
 87	}
 88	
 89	/**
 90	 * Returns the mtime of a file, or `null` if the file does not exist.
 91	 */
 92	async function getMtime(filePath: string): Promise<Date | null> {
 93	  try {
 94	    const s = await stat(filePath);
 95	    return s.mtime;
 96	  } catch {
 97	    return null;
 98	  }
 99	}
