298	/**
299	 * Request body schema for PUT /api/model-assignments.
300	 */
301	const UpdateAssignmentsBodySchema = ModelAssignmentsSchema;
302	
303	/**
304	 * Validates and persists model assignments.
305	 *
306	 * Validation:
307	 * - All model UUIDs referenced in the body must exist in the model registry.
308	 * - All persona keys in `persona_models` must appear as `id` values in
309	 *   `name-mapping.json`. Returns 400 when `name-mapping.json` doesn't exist.
310	 *
311	 * @param body - Raw parsed JSON request body.
312	 */
313	export async function handleUpdateAssignments(
314	  body: unknown
315	): Promise<ModelAssignments> {
316	  const parsed = UpdateAssignmentsBodySchema.safeParse(body);
317	  if (!parsed.success) {
318	    validationError(
319	      `Invalid assignments data: ${parsed.error.issues.map((i) => i.message).join('; ')}`
320	    );
321	  }
322	
323	  const data = parsed.data;
324	
325	  // 1. Validate name-mapping.json exists and load valid persona IDs
326	  let nameMappingRaw: string;
327	  try {
328	    nameMappingRaw = await readFile(nameMappingPath(), 'utf-8');
329	  } catch {
330	    validationError(
331	      'name-mapping.json does not exist. Run a persona build first before updating assignments.'
332	    );
333	  }
334	
335	  let nameMapping: unknown;
336	  try {
337	    nameMapping = JSON.parse(nameMappingRaw!);
338	  } catch {
339	    validationError('name-mapping.json is not valid JSON.');
340	  }
341	
342	  if (!Array.isArray(nameMapping)) {
343	    validationError('name-mapping.json must be a JSON array.');
344	  }
345	
346	  const validPersonaIds = new Set<string>(
347	    (nameMapping as Array<{ id?: unknown }>)
348	      .filter((e) => typeof e.id === 'string')
349	      .map((e) => e.id as string)
350	  );
351	
352	  // 2. Validate all persona keys in persona_models are valid persona IDs
353	  for (const personaKey of Object.keys(data.persona_models)) {
354	    if (!validPersonaIds.has(personaKey)) {
355	      validationError(
356	        `One or more persona keys in persona_models are not valid. ` +
357	          `Found ${validPersonaIds.size} valid persona ${validPersonaIds.size === 1 ? 'ID' : 'IDs'} in name-mapping.json.`
358	      );
359	    }
360	  }
361	
362	  // 3. Validate all model UUIDs exist in the registry
363	  const models = await readModels();
364	  const validModelIds = new Set(models.map((m) => m.id));
365	
366	  if (data.default_model_uuid !== undefined && !validModelIds.has(data.default_model_uuid)) {
367	    validationError(
368	      'The default_model_uuid does not exist in the model registry.'
369	    );
370	  }
371	
372	  const invalidPersonaUUIDs = Object.entries(data.persona_models)
373	    .filter(([, uuid]) => !validModelIds.has(uuid));
374	  if (invalidPersonaUUIDs.length > 0) {
375	    validationError(
376	      `${invalidPersonaUUIDs.length} model UUID(s) in persona_models do not exist in the model registry.`
377	    );
378	  }
379	
380	  // 4. Persist
381	  await writeAssignments(data);
382	  return data;
383	}
384	
385	// ---------------------------------------------------------------------------
386	// POST /api/model-assignments/replace
387	// ---------------------------------------------------------------------------
388	
389	/**
390	 * Request body schema for POST /api/model-assignments/replace.
391	 */
392	const ReplaceModelBodySchema = z
393	  .object({
394	    old_model_id: z.string().uuid(),
395	    new_model_id: z.string().uuid(),
396	  })
397	  .strict();
398	
399	/**
400	 * Swaps all occurrences of `old_model_id` with `new_model_id` in the current
401	 * assignments.
402	 *
403	 * Rejects with 400 when:
404	 * - `old_model_id === new_model_id`
405	 * - `old_model_id` is not currently referenced in any assignment
406	 *
407	 * Both UUIDs must exist in the model registry.
408	 *
409	 * @param body - Raw parsed JSON request body.
410	 */
