561	 */
562	export async function handleRebuildPersonas(workspaceRoot: string): Promise<{
563	  success: true;
564	  output: string;
565	} | {
566	  success: false;
567	  output: string;
568	  exitCode: number;
569	}> {
570	  if (buildInProgress) {
571	    throw new ApiError(
572	      'CONFLICT',
573	      'A persona build is already in progress. Please wait for it to complete.'
574	    );
575	  }
576	
577	  buildInProgress = true;
578	
579	  try {
580	    const output = await new Promise<{ output: string; exitCode: number }>(
581	      (resolve) => {
582	        const scriptPath = join(workspaceRoot, 'scripts', 'build-personas.js');
583	        const child = spawn('node', [scriptPath], {
584	          cwd: workspaceRoot,
585	          env: process.env,
586	        });
587	
588	        const chunks: string[] = [];
589	
590	        child.stdout.on('data', (chunk: Buffer) => {
591	          chunks.push(chunk.toString());
592	        });
593	
594	        child.stderr.on('data', (chunk: Buffer) => {
595	          chunks.push(chunk.toString());
596	        });
597	
598	        child.on('close', (code: number | null) => {
599	          resolve({ output: chunks.join(''), exitCode: code ?? 1 });
600	        });

601	
602	        child.on('error', (err: Error) => {
603	          resolve({
604	            output: `Process error: ${err.message}`,
605	            exitCode: 1,
606	          });
607	        });
608	      }
609	    );
610	
611	    if (output.exitCode === 0) {
612	      return { success: true, output: output.output };
613	    } else {
614	      return { success: false, output: output.output, exitCode: output.exitCode };
615	    }
616	  } finally {
617	    buildInProgress = false;
618	  }
619	}
