1721	    await serveStatic(req, res, port);
1722	    return;
1723	  }
1724	
1725	  // Body-parsing routes — dispatched via declarative route table
1726	  if (await dispatchRoute(
1727	    req, res, method, url, port,
1728	    buildRoutes(ledgerRoot, configPath, orchestratorLogsDir, bootVersions)
1729	  )) {
1730	    return;
